import{_ as s,o as r,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const n="/assets/%E4%B8%AA%E4%BA%BA%E4%B8%AD%E5%BF%83-%E7%94%A8%E6%88%B7.u-2-kRhz.png",e="/assets/%E4%B8%AA%E4%BA%BA-%E7%AE%A1%E7%90%86%E6%9D%83%E9%99%90.aC8VSppp.png",i="/assets/%E7%AE%A1%E7%90%86%E6%9D%83%E9%99%90%E4%BF%AE%E6%94%B911.BsvBiOQE.jpg",p="/assets/%E7%A7%BB%E9%99%A4%E8%AE%BF%E9%97%AE11.DscNsXRV.png",l="/assets/%E9%82%80%E8%AF%B7%E6%96%B0%E7%94%A8%E6%88%B7.BPWglrlg.png",g="/assets/%E9%80%89%E6%8B%A9%E6%9D%83%E9%99%9011.D93QalQy.png",c="/assets/%E9%82%80%E8%AF%B7%E5%8F%91%E9%80%81%E6%88%90%E5%8A%9F.FLCeBwX7.png",E="/assets/%E6%8E%A5%E5%8F%97%E9%82%80%E8%AF%B7.DbUscj83.png",m="/assets/%E7%99%BB%E5%BD%95%E8%B7%B3%E8%BD%AC11.CwfqgJ2w.png",q=JSON.parse('{"title":"为普通用户授权","description":"","frontmatter":{"title":"为普通用户授权"},"headers":[],"relativePath":"beginners-guide/account/user-permissions.md","filePath":"beginners-guide/account/user-permissions.md","lastUpdated":1794292918000}'),h={name:"beginners-guide/account/user-permissions.md"};function u(_,t,d,B,A,b){return r(),a("div",null,[...t[0]||(t[0]=[o('<p>如果想要将资源分配给企业中不同的员工或者应用程序使用，为了避免分享自己的账号密码，您可以使用所有者用户的用户管理功能，给员工或应用程序的普通用户授予权限。</p><blockquote><p><strong>说明</strong></p><p>建议您遵循最小化原则，按需授予普通用户角色必要的权限。</p></blockquote><hr><h3 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h3><p>用户管理模块通过管理权限和移除访问功能修改用户权限。</p><h4 id="管理权限" tabindex="-1">管理权限 <a class="header-anchor" href="#管理权限" aria-label="Permalink to &quot;管理权限&quot;">​</a></h4><p>管理权限通过选择或取消选择权限项，完成对用户的权限调整。</p><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在个人资料列表单击<strong>用户管理</strong>，进入<strong>用户管理</strong>页面。</p><p><img src="'+n+'" alt="个人中心-用户.png"></p></li><li><p>在用户管理列表，找到不带有”所有者“标签的普通用户。单击<strong>管理权限</strong>，进入<strong>管理权限</strong>页面。</p><p><img src="'+e+'" alt="个人-管理权限.png"></p></li><li><p>在<strong>管理权限</strong>页面列表里，勾选或者取消勾选权限项，完成对用户的权限调整。</p><p><img src="'+i+'" alt="管理权限修改11.jpg"></p><blockquote><p><strong>说明</strong></p><p>可从以下维度精细化分配普通用户的权限配置。</p><ul><li><strong>账户信息类</strong>：修改账户信息、管理联系人信息等；</li><li><strong>产品管理类</strong>：查看 / 修改产品、管理域名 / 服务标签等；</li><li><strong>订单操作类</strong>：执行订单登录、查看 / 下新订单等；</li><li><strong>财务类</strong>：查看 / 支付账单、管理信用额度等；</li><li><strong>售后类</strong>：查看 / 提交工单、管理技术支持权限等。</li></ul></blockquote></li><li><p>单击<strong>保存修改</strong>。</p></li></ol><h4 id="移除访问" tabindex="-1">移除访问 <a class="header-anchor" href="#移除访问" aria-label="Permalink to &quot;移除访问&quot;">​</a></h4><p>移除访问用于用户访问权限的删除。</p><ol><li><p>在用户管理页面用户管理列表，单击<strong>移除访问</strong>。</p><p><img src="'+p+'" alt="移除访问11.png"></p></li><li><p>在移除访问确认页面单击<strong>确认</strong>。</p><blockquote><p><strong>权限说明</strong></p><p>标注 “<strong>所有者</strong>” 的用户为所有权限用户，这类用户对账户具备完全管理权限。</p></blockquote></li></ol><hr><h3 id="邀请新用户" tabindex="-1">邀请新用户 <a class="header-anchor" href="#邀请新用户" aria-label="Permalink to &quot;邀请新用户&quot;">​</a></h3><p>邀请新用户是将新用户邀请到您的帐户中。如果被邀请者已经有一个帐户，那么他们可以使用现有帐户作为访问您的帐户的登录凭据。如果此用户还没有帐户，则可以创建一个，注册用户可参考<a href="/beginners-guide/register-account/">注册 RakSmart 账号</a>。</p><h4 id="邀请规则" tabindex="-1">邀请规则 <a class="header-anchor" href="#邀请规则" aria-label="Permalink to &quot;邀请规则&quot;">​</a></h4><p>通过输入电子邮箱邀请新用户。如果被邀请者已有 RakSmart 账户，则会直接关联到当前账户；若无账户，则会自动创建新账户。</p><h4 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h4><ol><li><p>在用户管理页面<strong>邀请新用户</strong>区域，填写新用户邮箱。</p><p><img src="'+l+'" alt="邀请新用户.png"></p></li><li><p>为新用户选择<strong>所有权限</strong>或者通过<strong>选择权限</strong>按钮选择需要的权限。</p><p><img src="'+g+'" alt="选择权限11.png"></p></li><li><p>单击<strong>发送邀请</strong>。</p></li><li><p>页面显示”<strong>邀请发送成功</strong>“。</p><p><img src="'+c+'" alt="邀请发送成功.png"></p></li><li><p>被邀请者需要登录已注册 RakSmart 子账号的邮箱，确认被邀请信息。单击<strong>接受邀请</strong>。</p><p><img src="'+E+'" alt="接受邀请.png"></p></li></ol><h4 id="操作结果" tabindex="-1">操作结果 <a class="header-anchor" href="#操作结果" aria-label="Permalink to &quot;操作结果&quot;">​</a></h4><ol><li><p>在<strong>接受邀请</strong>页面填写子账户登录密码（若有），若之前没有使用邮箱创建 RakSmart 子账号，则选择注册账号。</p><p><img src="'+m+'" alt="登录跳转11.png"></p></li><li><p>在 RakSmart 登录页面输入已注册的子账号邮箱和密码，完成登录。</p></li></ol>',20)])])}const f=s(h,[["render",u]]);export{q as __pageData,f as default};
